\begin{proposition}[Regular set]\label{p1:arith:core}
Let
\[
 G_N=\{x\in I_N:\dim S_x=L\},\qquad Z_N^\circ=\sum_{x\in G_N}J_x.
\]
Then $|I_N\setminus G_N|=N^{o(1)}$, and
\begin{equation}\label{p1:arith:coretransfer}
 d_{\rm TV}(\Law(Z_N),\Law(Z_N^\circ))+
 |\E Z_N-\lambda|+|\E Z_N^\circ-\lambda|
 \ll_C N^{-1+o(1)}.
\end{equation}
More generally, for every deterministic $A\subset I_N$ and every choice of
affine targets on its windows,
\begin{equation}\label{p1:arith:marginalsum}
 \sum_{x\in A}|\P(A_xX=b_x)-p|\leq pN^{o(1)}.
\end{equation}
If the fixed moments of $Z_N$ are uniformly bounded, then, for every fixed
integer $j\geq1$ and every $\varepsilon>0$,
\begin{equation}\label{p1:arith:momenttransfer}
 \big|\E Z_N^j-\E(Z_N^\circ)^j\big|
 \ll_{C,j,\varepsilon}N^{-1+\varepsilon}.
\end{equation}
In particular the second factorial cumulants have the same transfer bound.
\end{proposition}

\begin{proposition}[Centered Bernoulli expansion]
\label{p1:alg:centred}
For every \(N\),
\begin{equation}
 \Law(Z_N)=\sum_{I\subseteq\mathcal I_N}
       c(I)\Delta^{*|I|}*\mathop{*}_{x\notin I}b_x .
 \label{p1:alg:centred-identity}
\end{equation}
The complementary convolution products are deterministic probabilities.
The terms of sizes zero and two are
\[
 \mathop{*}_{x}b_x+
 \sum_{|e|=2}c(e)\Delta^{*2}*\mathop{*}_{x\notin e}b_x.
\]
Terms of size one vanish.
\end{proposition}

\begin{lemma}[Full-support Fourier formula]
\label{p1:alg:fourier}
For nonempty \(I\subseteq\mathcal I_N\),
\begin{equation}
 c(I)=\Bigl(\prod_{x\in I}p_x\Bigr)
   \sum_{\substack{s_x\in S_x\setminus\{0\}\ (x\in I)\\
                         \sum_xs_x=0}}
                 \prod_{x\in I}\eta_x(s_x).
 \label{p1:alg:fourier-identity}
\end{equation}
Consequently,
\[
 |c(I)|\le\Bigl(\prod_{x\in I}p_x\Bigr)(2^{\rho_{\mathrm{rel}}(I)}-1)
           \le\Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho_{\mathrm{rel}}(I)}.
\]
If \(c(I)\ne0\), there is a relative relation meeting
every block of \(I\).
\end{lemma}

\begin{lemma}[Compatible-nullity majorant]
\label{p1:alg:compatible}
For every \(I\subseteq\mathcal I_N\),
\begin{equation}
 |c(I)|\le 2^{|I|}\Bigl(\prod_{x\in I}p_x\Bigr)2^{\rho_*(I)},\qquad
 \rho_*(I)\le\rho_{\mathrm{rel}}(I).
 \label{p1:alg:compatible-bound}
\end{equation}
Equality holds in the second inequality when \(q(I)>0\).
\end{lemma}

\begin{lemma}[Existence, uniqueness, and factorization]
\label{p1:alg:components}
Every finite family \(I\) has a unique finest direct
partition \(\mathcal P(I)\). For it,
\begin{equation}
 q(I)=\prod_{C\in\mathcal P(I)}q(C),\qquad
 c(I)=\prod_{C\in\mathcal P(I)}c(C),\qquad
 \rho_{\mathrm{rel}}(I)=\sum_{C\in\mathcal P(I)}\rho_{\mathrm{rel}}(C).
 \label{p1:alg:factorization}
\end{equation}
\end{lemma}

\begin{lemma}[Expansion at the first excluded prefix]
\label{p1:stop:polynomial}
Let $(u_x)_{x\in G}$ belong to a commutative unital algebra.
Then, as a polynomial identity,
\begin{equation}
 \prod_{x\in G}(1+t u_x)
 =\sum_{I\in\mathscr D}t^{|I|}\prod_{x\in I}u_x
  +\sum_{I\in\partial\mathscr D}
       t^{|I|}\prod_{x\in I}u_x
       \prod_{\substack{y\in G\\y>\max I}}(1+t u_y).
 \label{p1:stop:polynomial-identity}
\end{equation}
\end{lemma}

\begin{proposition}[A positive remainder kernel]
\label{p1:stop:measure}
For arbitrary dependence among the indicators,
\begin{align}
 \Law Z-T_{\mathscr D}
   &=\sum_{I\in\partial\mathscr D}\Delta^{*|I|}*\nu_I,
       \label{p1:stop:measure-identity}\\
 \nu_I
   &=\E\left[
        \left(\prod_{x\in I}J_x\right)
        \delta_{\sum_{y>\max I}J_y}
        \right].
       \notag
\end{align}
The measure $\nu_I$ is positive and has mass $q(I)$.  Consequently,
\begin{equation}
 \|\Law Z-T_{\mathscr D}\|_1
       \le \sum_{I\in\partial\mathscr D}2^{|I|}q(I).
 \label{p1:stop:norm}
\end{equation}
\end{proposition}

\begin{proposition}[Large rank loss after fixed sources]
\label{p1:fixed:targets}
For every fixed \(s\ge1\) and \(\eta,\varepsilon>0\),
\begin{equation}
 \sup_{x_1,\ldots,x_s\ {\rm distinct}}
 \#\{z\in I_N\setminus\{x_1,\ldots,x_s\}:
                   \delta_z\ge\eta L\}
       \ll_{s,C,\eta,\varepsilon}N^\varepsilon .
 \label{p1:fixed:targets-bound}
\end{equation}
The sources may be dependent or overlapping.
\end{proposition}

\begin{proposition}[Conditional sums and propagation]
\label{p1:fixed:propagation}
For every fixed \(s\ge1\) and \(\varepsilon>0\), uniformly
over compatible prescribed affine events at \(s\) distinct
sources,
\begin{equation}
 \sum_{z\notin\{x_1,\ldots,x_s\}}
 \P(J_z=1\mid J_{x_1}=\cdots=J_{x_s}=1)
       \ll_{s,C,\varepsilon}N^\varepsilon .
 \label{p1:fixed:conditional}
\end{equation}
This assertion also holds when the affine prescriptions
are replaced by homogeneous ones. If a family of ordered
\(s\)-tuples has total positive joint mass \(W_{s,N}\),
the mass of its extensions to ordered distinct \(r\)-tuples,
for fixed \(r\ge s\), is
\begin{equation}
 W_{s\to r,N}\ll_{r,C,\varepsilon}N^\varepsilon W_{s,N}.
 \label{p1:fixed:propagate}
\end{equation}
In particular, the mass of fixed \(r\)-tuples containing
a local defect or a compatible contact is
\(O_{r,C,\varepsilon}(N^{-1+\varepsilon})\).
\end{proposition}

\begin{lemma}[Counting a small truncated squarefree kernel]
\label{p1:core:rankin}
For fixed $1/2<\sigma<1$, fixed $C_1>0$, and $T\ge1$,
\begin{equation}
 \#\{v\le C_1N:K_Y(v)\le T\}
 \ll_{\sigma,C_1}N^\sigma T^{1-\sigma}
       \exp(C_\sigma Y^{1-\sigma}).
 \label{p1:core:rankin-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Counting moderate certificates]
\label{p1:core:moderate}
Let $\mathcal U_r$ be the ordered lists of $r$ original windows having
such a certificate, and set
$m=\lceil 2\log(3N)/\log Y\rceil$. Then
\begin{equation}
 |\mathcal U_r|
 \le36rB^4 2^{r-1}N^rT^{-2}(rB)^m.
 \label{p1:core:moderate-count}
\end{equation}
For every fixed $u>0$,
\begin{equation}
 \sum_{r\ge1}\frac{(up)^r}{r!}|\mathcal U_r|
 \le N^{-2\beta+4/A_0+o(1)}.
 \label{p1:core:moderate-baseline}
\end{equation}
\end{lemma}

\begin{lemma}[Incoming and outgoing saturation degrees]
\label{p1:core:degrees}
Uniformly in the fixed vertex,
\begin{equation}
 \deg^+(x),\deg^-(x)\le N^{2/A_0+o(1)},
 \qquad \Delta(\Gamma)\le N^{2/A_0+o(1)}.
 \label{p1:core:degree-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Positivity of the quadratic Poisson correction]
\label{p1:close:positivity}
Let $\mu>0$, $\alpha\in\mathbb R$, and
$\theta=\mu-\lfloor\mu\rfloor$.  Then $Q_{\mu,\alpha}$ is a
probability measure if and only if
\begin{equation}
 0\le\alpha\le
       \frac{2\mu^2}{\mu+\theta(1-\theta)}.
 \label{p1:close:positivity-range}
\end{equation}
Its masses are
\begin{equation}
 Q_{\mu,\alpha}\{k\}
 =e^{-\mu}\frac{\mu^k}{k!}
   \left[1+\frac{\alpha}{2\mu^2}
                    \bigl((k-\mu)^2-k\bigr)\right],
 \qquad k\ge0.
 \label{p1:close:charlier-masses}
\end{equation}
\end{lemma}

\begin{proposition}[Uniform moments for short split products]
\label{p13:short:moments}
For every fixed even integer \(v\ge2\), with the preceding notation,
\begin{equation}
 \E\left|\sum_{n\asymp N}f(P_A(n))\right|^v
 \le N^{v/2+c[v(v-1)+2]\log2+o(1)}.
 \label{p13:short:moment-bound}
\end{equation}
In particular, for each fixed \(v\) and \(\varepsilon>0\),
one may choose \(c>0\) so that the \(L^v\) norm is
\(O(N^{1/2+\varepsilon})\), uniformly in all the indicated
motifs. The summation interval may have any fixed comparable
length and positive height.
\end{proposition}

\begin{theorem}[Conditional full-support count]
\label{p13:half:conditional}
Fix \(r\ge1\), \(s\ge0\), \(D>0\), and \(\varepsilon>0\).
Let \(V_{\rm old}\) be the space generated by all values
in \(s\) fixed source blocks. Uniformly in those sources,
the number of lists of distinct new centres \(z_1,\ldots,z_r\)
such that
\begin{equation}
 u_i\in S_{z_i}\setminus\{0\}\quad(1\le i\le r),
 \qquad \sum_i u_i\in V_{\rm old}
 \label{p13:half:condition}
\end{equation}
for some \(u_i\), is \(O_{r,s,D,C,\varepsilon}(N^{r/2+\varepsilon})\).
The \(u_i\) need not remain nonzero modulo \(V_{\rm old}\).
The source blocks may overlap or be dependent.
\end{theorem}

\begin{theorem}[A short basis with a controlled loss of dimension]
\label{p13:rig:short-basis}
For every fixed $a\in(0,1)$ there is a subspace $\mathcal K_a$
of complete relations of the pair, with injective projections
onto each physical block and onto the common square class,
such that
\begin{equation}
 \dim\mathcal K_a\ge d_{xy}-\frac23B\log(1/a)
                    -O_{a,C}\!\left(\frac B{\sqrt{\log B}}\right).
 \label{p13:rig:short-dimension}
\end{equation}
It has a basis whose vectors have total physical support at most
\begin{equation}
                    O_{a,C}\!\left(
                         \frac{B^a\log B}{\log\log B}\right).
 \label{p13:rig:short-support}
\end{equation}
Every nonzero vector selects a nonempty even set in each block
and has nonzero common square class.  Neither compatibility nor
nonalignment is assumed.
\end{theorem}

\begin{proposition}[Integer fibres in the offset grid]
\label{p13:rig:grid-fibres}
Under the hypotheses of Theorem~\ref{p13:rig:common-curve},
assume both physical projections of $V$ are injective.
Put $D=\deg C_0$, $d_X=\deg_XC_0$, $d_Y=\deg_YC_0$.
For an absolute constant $c$,
\begin{equation}
 \#\{(u,v)\in[-B,B]^2\cap\Z^2:C_0(-u,-v)=0\}
       \ge\max(d_X,d_Y)(t-1-cD^2).
 \label{p13:rig:grid-count}
\end{equation}
A negative right side may be replaced by zero.
\end{proposition}

\begin{proposition}[Rank on a known alignment]
\label{p13:rig:aligned}
Suppose $bx-ay=h$, where $(a,b)=1$, $1\le a,b\le B^3$,
and $|h|\le(a+b)B$.  For every fixed $\tau\in(0,1)$,
\begin{equation}
 d_{xy}\le\frac B{\max(a,b)}+\frac23B\log(1/\tau)
                    +O_{\tau,C}(B/\sqrt{\log B}).
 \label{p13:rig:aligned-quantitative}
\end{equation}
For distinct compatible centres this implies, uniformly
over aligned pairs,
$d_{xy}\le B/2+o_C(B)$.  If such a pair has an alignment
with $a=b=1$, then $d_{xy}=o_C(B)$.
\end{proposition}

\begin{lemma}[A sharp rational overlap inequality]
\label{p13:third:rational-rank}
For all integers $u<v<w<2u$ with $(u,v,w)=1$,
\begin{equation}
 D(u,v,w)\leq\frac{19}{30}.
 \label{p13:third:1930}
\end{equation}
Equality holds for $(u,v,w)=(10,12,15)$.
This is an inequality for the canonical coincidence geometry; arithmetic
relations among the distinct normalized values require a separate bound.
\end{lemma}

\begin{proposition}[Norms of Poisson differences]
\label{p1:discussion:charlier-norm}
For $\mu>0$, put $\pi_\mu(k)=e^{-\mu}\mu^k/k!$ when $k\ge0$
and $\pi_\mu(k)=0$ when $k<0$.  Define
\[
 u_\pm=\mu+\frac12\pm\frac{\sqrt{4\mu+1}}2,\qquad
 a=\lfloor u_-\rfloor+1,\qquad b=\lceil u_+\rceil-1.
\]
Then
\begin{equation}
 \|\Pi_\mu*\Delta^{*2}\|_1
 =2\bigl\{\pi_\mu(a-1)-\pi_\mu(a-2)
             +\pi_\mu(b-1)-\pi_\mu(b)\bigr\}.
 \label{p1:discussion:finite-norm}
\end{equation}
More generally, for every integer $r\ge0$,
\begin{equation}
 \|\Pi_\mu*\Delta^{*r}\|_1
       \le\min\left\{2^r,\frac{\sqrt{r!}}{\mu^{r/2}}\right\}.
 \label{p1:discussion:general-norm}
\end{equation}
In particular,
\begin{equation}
 \|\Pi_2*\Delta^{*2}\|_1=\frac{10}{3e^2},
 \qquad \mathcal C(2)=\frac{5}{6e^2}.
 \label{p1:discussion:lambda-two}
\end{equation}
\end{proposition}

\begin{lemma}[Local and global defect counts]\label{p1:arith:defects}
Suppose $B\asymp\log N$ and $H\asymp B$, with fixed comparison constants.
Any interval of diameter $O(B)$ in $[cN,CN]$ contains
$O(B/\log B)$ $H$-defective integers.  Moreover
\begin{align}
 \#\{n\leq CN:K_H(n)=1\}&\leq N^{1/2+o(1)},\label{p1:arith:onedfect}\\
 \#\{x\in I_N:V_x\text{ contains two }H\text{-defective integers}\}
   &\leq N^{o(1)}.\label{p1:arith:twodefect}
\end{align}
All statements remain valid after fixed dilations and translations of the
intervals.
\end{lemma}

\begin{lemma}[Two small kernels]
\label{p13:half:small-kernels}
For every fixed \(q>0\) and \(\varepsilon>0\),
\(\#\mathcal X_q\ll_{q,D,C,\varepsilon}N^{q+\varepsilon}\).
\end{lemma}

\begin{lemma}[Heredity and boundary nullity]
\label{p1:stop:class}
The family $\mathscr D$ is hereditary.  Each non-direct member
contains a unique dependent pair $e\in E_N$, and its nullity
equals $\rho(e)$.  Hence, for all sufficiently large $N$,
\begin{equation}
 \partial\mathscr D
 \subseteq\{I\notin\mathscr D:
                 0<\rho(I)\le 4L/3+O(1)<3L/2\}.
 \label{p1:stop:boundary-nullity}
\end{equation}
\end{lemma}

\begin{lemma}[Large boundary families]
\label{p1:stop:tail}
Uniformly in the fixed critical band,
\begin{equation}
 \sum_{\substack{I\in\partial\mathscr D\\|I|>K_N}}
           2^{|I|}q(I)=O_C(N^{-3/2}).
 \label{p1:stop:tail-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Bounds for the independent deficits]
\label{p1:close:deficit-bounds}
For every fixed $\varepsilon>0$,
\begin{equation}
 F\ll_\varepsilon N^{-4/5+\varepsilon}+B/N,
 \qquad
 \mathfrak G\ll_\varepsilon N^{-1+\varepsilon}.
 \label{p1:close:deficit-rates}
\end{equation}
\end{lemma}

\begin{proposition}[Evaluation of the retained polynomial]
\label{p1:close:retained-reference}
For the class $\mathscr D$,
\begin{equation}
 T_{\mathscr D}
 =\mathsf B_\beta-\sum_{r\ge0}(F_r+G_r)\Delta^{*r},
 \qquad
 \|T_{\mathscr D}-\mathsf B_\beta\|_1\le F+\mathfrak G.
 \label{p1:close:retained-identity}
\end{equation}
\end{proposition}

\begin{proposition}[Support and factorial lattice]
\label{p1:limits:lattice}
For every $N\ge2$ and $L\ge1$,
\begin{equation}
 0\le Z\le R_N,\qquad
 \E(Z)_j\in j!p^j\mathbb Z_{\ge0}\quad(j\ge1).
 \label{p1:limits:lattice-eq}
\end{equation}
\end{proposition}

\begin{proposition}[Exact local blocks]
\label{p1:limits:local-blocks}
For sufficiently large $N$ in a fixed critical band, the intervals
$B_S$, $S\in\mathcal R$, are nonempty and pairwise disjoint.
They partition the locally deficient starts.  On such a block,
\begin{equation}
 \P(J_x=1)=
 \begin{cases}0,&x=a_S+1,\\2p,&x\in B_S\setminus\{a_S+1\},\end{cases}
 \qquad
 \sum_{x\in B_S}J_x\sim\mathrm{Bernoulli}\bigl(2p(|B_S|-e_S)\bigr).
 \label{p1:limits:block-law}
\end{equation}
Outside these blocks the marginal is $p$.  In particular,
\begin{align}
 \E Z-Np&=p\sum_{S\in\mathcal R}(|B_S|-2e_S),
       \label{p1:limits:block-mean}\\
 \sum_{x\in I_N}|\P(J_x=1)-p|
       &=p\sum_{S\in\mathcal R}|B_S|.
       \label{p1:limits:block-absolute}
\end{align}
A full block contributes $p(L-d_S-1)$ to the mean discrepancy.
There are at most two blocks truncated by the endpoints of $I_N$,
whose total boundary correction is at most $2Lp$ in absolute value.
\end{proposition}

\begin{proposition}[A quantified effective support]
\label{p1:limits:effective-tail}
For each fixed $D>0$ and integer $r\ge0$, there is a constant
$K=K(C,D,r)$ such that
\begin{equation}
 \E[Z_N^r;Z_N>A_N]\le N^{-D},\qquad
 A_N=\left\lceil\sqrt N\exp\left(\frac{K\log N}
                                    {(\log\log N)^{2/3}}\right)\right\rceil
 \label{p1:limits:effective-threshold}
\end{equation}
for sufficiently large $N$.  Hence, for every fixed
$\eta,D>0$ and integer $r\ge0$,
$\E[Z_N^r;Z_N>N^{1/2+\eta}]=O(N^{-D})$.
\end{proposition}

\begin{proposition}[Divergence of the real exponential moment]
\label{p1:limits:cylinder}
Along odd primes $q\to\infty$, put $N_q=2^{q-1}$ and
$L_q=q-1$.  For every fixed $t>2$,
\begin{equation}
 \liminf_{q\to\infty}\frac{\log N_q}{N_q}
        \log\E e^{tZ_{N_q,L_q}}\ge(t-2)\log2>0.
 \label{p1:limits:exponential-divergence}
\end{equation}
The same bound holds for the count of positive runs alone.
\end{proposition}

\begin{lemma}[Deleting large private ranks]
\label{p1:limits:peeling}
Let $A$ be a compatible family of $m$ affine events, each with
constraint-space dimension $L$, and put
$R=\dim\sum_{x\in A}S_x$ and $p=2^{-L}$.
For an integer $1\le t\le L$, repeatedly remove a member whose
current private rank is at least $t$.  The final family $A'$ satisfies
\[
 |A'|\ge m-R/t,\qquad
 \dim\sum_{x\in A'}S_x\le R,\qquad
 r_x(A')<t\quad(x\in A'),
\]
where $r_x(I)=\dim\sum_{y\in I}S_y-
\dim\sum_{y\in I\setminus\{x\}}S_y$.
Each direct component $C$ of $A'$ satisfies
\begin{equation}
 c(C)\ge(1-|C|p2^t)q(C)\ge(1-mp2^t)q(C).
 \label{p1:limits:positive-core}
\end{equation}
If $m-R/t>0$ and $D=R/(m-R/t)$, some such component obeys
\begin{equation}
 \frac{\dim\sum_{x\in C}S_x}{|C|}\le D,\qquad
 |C|\ge L/D,\qquad \rho(C)\ge L^2/D-L.
 \label{p1:limits:rank-density}
\end{equation}
\end{lemma}

\begin{proposition}[A real component of quadratic nullity]
\label{p1:limits:large-component}
Along the subsequence of Proposition~\ref{p1:limits:cylinder},
there are compatible connected families $C_q\subset G_{N_q}$
containing no good pair and satisfying
\begin{equation}
 \begin{gathered}
 |C_q|\ge(\kappa-o(1))L_q,\qquad
 \rho_*(C_q)=\rho(C_q)\ge(\kappa-o(1))L_q^2,\\
 c(C_q)\ge(1-O(L_q^{-1/2}))q(C_q)>0,\qquad
 \kappa=\frac{6\log2}{17}.
 \end{gathered}
 \label{p1:limits:quadratic-nullity}
\end{equation}
\end{proposition}

\begin{lemma}[A scalar recurrence criterion]
\label{p1:limits:stein}
If $0\le\theta<\min(\mu,1/2)$, then
\begin{equation}
 \TV(P,H_{\mu,\theta})
       \le\frac{\mathcal R(P;\mu,\theta)}{1-2\theta}.
 \label{p1:limits:stein-bound}
\end{equation}
If $m=\E X>0$, $\kappa=\Var X-\E X$ and
$0\le\kappa<\min(m,1/2)$, the size-biased variable $X^s$
satisfies the exact identity
\begin{equation}
 \mathcal R(\Law X;m,\kappa)
 =2m\TV\left(\Law X^s,
       (1-\kappa/m)\Law(X+1)+(\kappa/m)\Law(X+2)\right).
 \label{p1:limits:size-bias}
\end{equation}
\end{lemma}

\begin{proposition}[The signed Palm measure]
\label{p1:limits:signed-palm}
For any finite family of indicators, let $Z=\sum_xJ_x$,
$p_x=\E J_x$, $m=\E Z$, $P=\Law Z$, and $T_x=Z-J_x$.
Omit sources with $p_x=0$, and define
\[
 \mathcal D=\sum_xp_x
       \{\Law(T_x\mid J_x=1)-\Law(T_x)\}.
\]
Then
\begin{equation}
 \big|\mathcal R(P;m,\theta)
       -\|\mathcal D-\theta\Delta*P\|_1\big|
       \le2\sum_xp_x^2.
 \label{p1:limits:signed-palm-bound}
\end{equation}
Writing $q_A=\E\prod_{x\in A}J_x$, the coefficient of
$(z-1)^j$ in its generating polynomial is exactly
\begin{equation}
 d_j=\sum_{|A|=j}\sum_{x\notin A}(q_{A\cup\{x\}}-p_xq_A).
 \label{p1:limits:signed-palm-coefficients}
\end{equation}
If all $n$ marginals equal $p$ and
$B_j=\E\binom Zj$, this becomes
$d_j=(j+1)B_{j+1}-p(n-j)B_j$.
\end{proposition}

\begin{lemma}[A recurrence norm equivalent to total variation]
\label{p1:limits:weighted-residual}
For every $P$ and $\mu>0$,
\begin{equation}
 e^{-\mu}\TV(P,\Pi_\mu)\le\mathcal V(P;\mu)
       \le2(1+\mu)\TV(P,\Pi_\mu).
 \label{p1:limits:weighted-equivalence}
\end{equation}
Moreover, if $0<\mu,\nu\le M$, then
\begin{equation}
 |\mathcal V(P;\mu)-\mathcal V(Q;\nu)|
       \le2(1+M)\TV(P,Q)+|\mu-\nu|.
 \label{p1:limits:weighted-stability}
\end{equation}
\end{lemma}

\begin{lemma}[An integer product tail]
\label{p1:offset:integer-tail}
For fixed $s>1$ and $T\ge1$,
\[
 \sum_{\substack{a,b\ge1\\ab>T}}(ab)^{-s}
       \ll_s T^{1-s}\log(2T).
\]
\end{lemma}

\begin{proposition}[A forced plane uses all three coordinates]
\label{p1:offset:forced-plane}
Two distinct shared primes satisfy $\ell\ell'\le6NB$.
If three distinct shared primes have product greater than $18NB^2$,
then $X$ belongs to a plane of $\mathscr P_B$ whose normal satisfies
$A_1A_2A_3\ne0$. Every further shared prime $\ell>12B^3$ has
\begin{equation}
 A\cdot u_\ell=-h.
 \label{p1:offset:subsequent-offset}
\end{equation}
The primitive mass of triples belonging to two distinct planes of
$\mathscr P_B$ is $O_C(N^{-1+o(1)})$.
\end{proposition}

\begin{proposition}[Profiles depend on the interval]
\label{p1:consequences:macro}
In the dyadic critical band, writing $B=3k+r$, $0\le r<3$,
\begin{equation}
 R_{\rm rat}(I_N,B)\sim R_{\rm al}(I_N,B)
       \sim \frac{3+r}{18}NB2^k,
 \qquad
 R_{\rm al}(I_N,B)-R_{\rm rat}(I_N,B)
       =O_{C,\varepsilon}(N^{5/4+\varepsilon}).
 \label{p1:consequences:dyadic-positive}
\end{equation}
Fix $0<\delta<1$, let $A_{M,\delta}=[\lceil M^\delta\rceil,M)
\cap\mathbb Z$, and suppose $|L-\log_2M|\le C$.
For $B=2k+r$, $0\le r<2$,
\begin{equation}
 R_{\rm rat}(A_{M,\delta},B)\sim R_{\rm al}(A_{M,\delta},B)
       \sim\frac{2+r}{4}MB2^k,
 \label{p1:consequences:macro-positive}
\end{equation}
and their difference is $O_{C,\delta,\varepsilon}(M^{4/3+\varepsilon})$.
For the signed profile, write instead $L=2m+s$, $0\le s<2$.
Then
\begin{align}
 C_{\rm al}(A_{M,\delta},L)
   &=(M-2M^\delta)S_{1,2}(L)
           +O_{C,\delta,\varepsilon}(M^{4/3+\varepsilon}),
          \label{p1:consequences:macro-signed}\\
 S_{1,2}(L)
   &=2^{m-1}\big[(s+1)m+s^2+s+4\big]-3L+1
       \qquad(m\ge1),\label{p1:consequences:S12}\\
 C_{\rm al}(A_{M,\delta},L)
   &\sim\frac{s+1}{4}ML2^m.
          \label{p1:consequences:macro-equivalent}
\end{align}
\end{proposition}

\begin{lemma}[A Rankin bound for offset patterns]
\label{p1:consequences:rankin-patterns}
For fixed $c,D_0>0$, $d\in\{2,3\}$ and $X\ge1$, put
$s=1+(d-1)/c$. Then
\begin{equation}
 \sum_{\substack{Q\le X\ {\rm squarefree}\\P^-(Q)>B^c}}
       (D_0B)^{d\omega(Q)}
 \le X^s\exp\{O_{c,D_0}(B/\log B)\}.
 \label{p1:consequences:rankin-primes}
\end{equation}
If instead the factors are arbitrary distinct integers
$g>B^c$, then, for every fixed $0<\zeta<1$ and
$s_\zeta=1+(d-1+\zeta)/c$,
\begin{equation}
 \sum_{\substack{A\subset\mathbb N\ {\rm finite}\\
                g>B^c\ (g\in A),\ \prod_{g\in A}g\le X}}
       (D_0B)^{d|A|}
 \le X^{s_\zeta}\exp\{O_{c,d,\zeta,D_0}(B^{1-\zeta})\},
 \label{p1:consequences:rankin-groups}
\end{equation}
where $D_0$ is fixed.
\end{lemma}

\begin{proposition}[A weighted count of every full support]
\label{p1:uniform:full-support}
For fixed \(s\ge2\), \(u>0\), and \(\varepsilon>0\),
\[
 \sum_{r=s}^{|G|}\frac{u^r}{r!}
     \sum_{\boldsymbol x\in\mathcal H_{r,N}}p^r
       \ll_{s,u,C,\varepsilon}N^{-2s/(2s+1)+\varepsilon}.
\]
\end{proposition}

\begin{proposition}[The replica formula and positive propagation]
\label{p1:uniform:replicas}
For \(r\) prescribed occurrences,
\begin{equation}
 \E\prod_{A\in\pi}
     \P(J_{x_i}=1\ (i\in A)\mid\mathcal F_Y)
       =p^r\eta_\pi2^{\dim K_\pi}.
 \label{p1:uniform:replica-formula}
\end{equation}
After any fixed number of compatible colored
sources, the sum of the conditional probabilities
of targets is \(O_\varepsilon(N^\varepsilon)\),
uniformly in \(Y\) and the coloring.
Here conditioning means prescribing these source events
in the replicated space; the common small-prime signs
are still averaged. Thus a positive random sum
\[
 R=\sum_{\boldsymbol x\in\mathcal A}w_{\boldsymbol x}
       \prod_{A\in\pi}
          \P(J_{x_i}=1\ (i\in A)\mid\mathcal F_Y),
\]
with fixed tuple length, fixed partition \(\pi\), and
nonnegative deterministic weights bounded by a fixed
power of \(\log N\),
satisfies for every fixed integer \(q\ge1\)
\begin{equation}
 \E R^q\ll_\varepsilon N^\varepsilon\E R,
 \label{p1:uniform:replica-moment}
\end{equation}
when its index set is a subfamily of all ordered
tuples of the stated fixed length.
\end{proposition}
